%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% H2 State Feedback Controller Design using LMI Formulation
% 
% This MATLAB code designs an H2 state feedback controller that minimizes
% the sum of squared H2 norms from disturbance to output and control input.
% 
% The optimization problem is formulated using the Schur complement lemma
% and bounded real lemma to handle the nonlinearity in the system structure.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

clc
clear all
close all

%% Load and prepare system data
load('data3.mat');
G3 = bj(data3, [5, 5, 5, 5, 1]);
G3_c = d2c(G3);
[A, B, C, D] = ssdata(G3_c);

%% H2 Controller Design via LMI
n = size(A, 1);
m = size(B, 2);
p = size(C, 1);

X = sdpvar(n, n, 'symmetric');
Y = sdpvar(m, n, 'full');
Z = sdpvar(p, p, 'symmetric');

epsilon = 1e-6;

% Bounded Real Lemma for stability
LMI1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -epsilon*eye(n)];

% Schur Complement Lemma for output term
LMI2 = [[Z, C*X; X*C', X] >= 0];

% Positive definiteness
LMI3 = [X >= epsilon*eye(n)];

LMIs = [LMI1, LMI2, LMI3];
Objective = trace(Z);
options = sdpsettings('solver','sedumi','verbose',0);
diagnostics = optimize(LMIs, Objective, options);

if diagnostics.problem == 0
    X_opt = value(X);
    Y_opt = value(Y);
    K = Y_opt / X_opt;

    % Closed-loop analysis
    A_cl = A - B*K;
    sys_cl = ss(A_cl, B, C, D);
    figure; step(sys_cl); title('H2 Controller Step Response');

    % Compare with LQR
    Q_lqr = C'*C + 1e-3*eye(n);
    R_lqr = eye(m);
    K_lqr = lqr(A, B, Q_lqr, R_lqr);
    sys_cl_lqr = ss(A-B*K_lqr, B, C, D);
    hold on; step(sys_cl_lqr); legend('H2', 'LQR');
else
    error('Optimization failed');
end
