def parse_vue_loader_syntax(loader_string: str) -> Dict[str, Any]:
    """
    Parse and explain Vue.js webpack loader syntax in detail.

    Args:
        loader_string: The complex webpack loader string from the error message

    Returns:
        Dictionary with parsed components and explanations
    """
    # Split the loader chain by '!' to get individual loaders
    loader_parts = loader_string.split('!')

    parsed_result = {
        'original_string': loader_string,
        'total_parts': len(loader_parts),
        'parts': [],
        'error_location': None,
        'file_reference': None,
        'summary': {}
    }

    # Extract the target file (usually at the end)
    if loader_parts and loader_parts[-1].endswith('.vue'):
        parsed_result['file_reference'] = loader_parts[-1]
        parsed_result['error_location'] = f"Processing Vue component: {loader_parts[-1]}"

    # Parse each part of the loader chain
    for i, part in enumerate(loader_parts):
        part_info = {
            'position': i + 1,
            'raw': part,
            'type': None,
            'loader_name': None,
            'options': None,
            'explanation': None,
            'purpose': None
        }

        # Check for special prefixes
        if part.startswith('!!'):
            part_info['type'] = 'inline_loader'
            part_info['explanation'] = 'Double exclamation (!!) means "inline loader" - bypasses all configured loaders'
            clean_part = part[2:]
        elif part.startswith('!'):
            part_info['type'] = 'loader_chain_break'
            part_info['explanation'] = 'Single exclamation (!) separates loaders in the chain'
            clean_part = part[1:]
        else:
            part_info['type'] = 'normal_loader'
            clean_part = part

        # Extract loader name and options
        if '?' in clean_part:
            loader_name, options_str = clean_part.split('?', 1)
            part_info['loader_name'] = loader_name

            # Try to parse JSON options
            try:
                if options_str.strip().startswith('{'):
                    part_info['options'] = json.loads(options_str)
                else:
                    part_info['options'] = options_str
            except json.JSONDecodeError:
                part_info['options'] = options_str
        else:
            part_info['loader_name'] = clean_part

        # Add detailed explanations for each loader type
        if part_info['loader_name']:
            explanation_map = {
                'vue-style-loader': {
                    'purpose': 'Inject CSS styles into the DOM',
                    'details': 'Vue-specific version of style-loader. Extracts CSS from Vue components and injects it into the document as style tags.',
                    'why_needed': 'Required for Vue Single File Components (SFCs) to handle scoped styles'
                },
                'css-loader': {
                    'purpose': 'Process CSS files',
                    'details': 'Interprets @import and url() like import/require() and resolves them. Converts CSS to CommonJS modules.',
                    'options_explained': {
                        'minimize': 'Whether to minimize CSS (false = no minification)',
                        'sourceMap': 'Whether to generate source maps (false = no source maps)'
                    }
                },
                '../../node_modules/vue-loader/lib/style-compiler/index': {
                    'purpose': 'Vue style compiler',
                    'details': 'Compiles style blocks from Vue Single File Components. Handles scoped styles, CSS modules, and pre-processors.',
                    'options_explained': {
                        'vue': 'true = Vue-specific compilation',
                        'id': 'Unique component ID for scoped styles',
                        'scoped': 'true = enables scoped CSS',
                        'hasInlineConfig': 'false = no inline configuration'
                    }
                },
                'less-loader': {
                    'purpose': 'Compile LESS to CSS',
                    'details': 'Loads and compiles LESS files. Requires the less package to be installed.',
                    'options_explained': {
                        'sourceMap': 'Whether to generate source maps for LESS compilation'
                    }
                },
                '../../node_modules/vue-loader/lib/selector': {
                    'purpose': 'Vue component selector',
                    'details': 'Selects specific blocks from Vue Single File Components (template, script, styles).',
                    'options_explained': {
                        'type': 'styles = selects style blocks',
                        'index': '0 = first style block'
                    }
                }
            }

            # Find matching explanation
            for key, explanation in explanation_map.items():
                if key in part_info['loader_name']:
                    part_info['purpose'] = explanation['purpose']
                    part_info['explanation'] = explanation['details']

                    # Add option explanations if available
                    if part_info['options'] and 'options_explained' in explanation:
                        option_explanations = {}
                        if isinstance(part_info['options'], dict):
                            for opt_key, opt_value in part_info['options'].items():
                                if opt_key in explanation['options_explained']:
                                    option_explanations[opt_key] = {
                                        'value': opt_value,
                                        'explanation': explanation['options_explained'][opt_key]
                                    }
                        if option_explanations:
                            part_info['option_explanations'] = option_explanations
                    break

        parsed_result['parts'].append(part_info)

    # Create a summary
    parsed_result['summary'] = {
        'processing_flow': ' → '.join([p['loader_name'] or p['raw'] for p in parsed_result['parts']]),
        'target_file': parsed_result['file_reference'],
        'main_components': [
            'Vue Single File Component processor',
            'LESS compiler',
            'CSS processor',
            'Style injector'
        ],
        'error_context': 'This error occurs during webpack module resolution when trying to process a Vue component'
    }

    return parsed_result
