For production use, consider:

```rust
pub fn get_sym_json_path(
    args: &DownloadArgs,
    region_json: &RegionJson,
) -> Result<Vec<String>, RegionError> {
    use unicase::UniCase;

    let available_regions: Vec<_> = region_json._Regions_.keys().cloned().collect();
    let mut missing = Vec::new();
    let mut paths = Vec::new();

    for region in &args.region {
        let key = UniCase::new(region.to_string());
        match region_json._Regions_.get(&key) {
            Some(path) => paths.push(path.clone()),
            None => missing.push(region.clone()),
        }
    }

    if missing.is_empty() {
        Ok(paths)
    } else {
        Err(RegionError::new(missing, available_regions))
    }
}
