class PersonalInfoForm extends StatefulWidget {
  final String uid;
  const PersonalInfoForm({Key? key, required this.uid}) : super(key: key);

  @override
  _PersonalInfoFormState createState() => _PersonalInfoFormState();
}

class _PersonalInfoFormState extends State<PersonalInfoForm> {
  final _formKey = GlobalKey<FormState>();
  final _firstNameController = TextEditingController();
  final _lastNameController = TextEditingController();
  File? _profileImage;
  bool _isLoading = false;

  // Name validation
  bool _validateName(String name) {
    final nameRegex = RegExp(r'^[a-zA-Z]{2,}(?: [a-zA-Z]+){0,2}$');
    return nameRegex.hasMatch(name);
  }

  Future<void> _pickImage() async {
    final pickedFile = await ImagePicker().pickImage(
      source: ImageSource.gallery,
      maxWidth: 800,
      maxHeight: 800,
      imageQuality: 85,
    );

    if (pickedFile != null) {
      setState(() {
        _profileImage = File(pickedFile.path);
      });
    }
  }

  Future<void> _submitForm() async {
    if (!_formKey.currentState!.validate()) return;
    if (_profileImage == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Please select a profile picture')));
      return;
    }

    setState(() => _isLoading = true);

    try {
      // 1. Upload profile picture to Firebase Storage
      final imageUrl = await _uploadProfileImage();

      // 2. Save all data to Firestore
      await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.uid)
          .set({
            'firstName': _firstNameController.text.trim(),
            'lastName': _lastNameController.text.trim(),
            'profileImage': imageUrl,
            'updatedAt': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));

      // Navigate to next step
      Navigator.push(context, MaterialPageRoute(
        builder: (_) => BodyMetricsForm(uid: widget.uid)));

    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error: ${e.toString()}')));
    } finally {
      setState(() => _isLoading = false);
    }
  }

  Future<String> _uploadProfileImage() async {
    final ref = FirebaseStorage.instance
        .ref()
        .child('profile_pictures/${widget.uid}.jpg');

    await ref.putFile(_profileImage!);
    return await ref.getDownloadURL();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Personal Information')),
      body: SingleChildScrollView(
        padding: EdgeInsets.all(20),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              // Profile Picture Picker
              GestureDetector(
                onTap: _pickImage,
                child: CircleAvatar(
                  radius: 60,
                  backgroundImage: _profileImage != null 
                      ? FileImage(_profileImage!) 
                      : null,
                  child: _profileImage == null
                      ? Icon(Icons.camera_alt, size: 40)
                      : null,
                ),
              ),
              SizedBox(height: 20),

              // First Name Field
              TextFormField(
                controller: _firstNameController,
                decoration: InputDecoration(labelText: 'First Name'),
                validator: (value) {
                  if (value == null || value.isEmpty) {
                    return 'Please enter your first name';
                  }
                  if (!_validateName(value)) {
                    return 'Please enter a valid name (2+ letters)';
                  }
                  return null;
                },
              ),
              SizedBox(height: 20),

              // Last Name Field
              TextFormField(
                controller: _lastNameController,
                decoration: InputDecoration(labelText: 'Last Name'),
                validator: (value) {
                  if (value == null || value.isEmpty) {
                    return 'Please enter your last name';
                  }
                  if (!_validateName(value)) {
                    return 'Please enter a valid name (2+ letters)';
                  }
                  return null;
                },
              ),
              SizedBox(height: 30),

              // Submit Button
              ElevatedButton(
                onPressed: _isLoading ? null : _submitForm,
                child: _isLoading
                    ? CircularProgressIndicator()
                    : Text('Continue'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
