class _BodyMetricsFormState extends State<BodyMetricsForm> {
  final _formKey = GlobalKey<FormState>();
  final _weightController = TextEditingController();
  final _heightController = TextEditingController();
  String? _selectedBodyType;
  bool _isLoading = false;
  final List<String> _bodyTypes = ['Ectomorph', 'Mesomorph', 'Endomorph'];

  Future<void> _submitForm() async {
    if (!_formKey.currentState!.validate()) return;
    if (_selectedBodyType == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Please select a body type')));
      return;
    }

    setState(() => _isLoading = true);

    try {
      // Calculate BMI
      final weight = double.parse(_weightController.text);
      final height = double.parse(_heightController.text);
      final bmi = weight / pow(height / 100, 2);

      // Save to Firestore
      await FirebaseFirestore.instance
          .collection('users')
          .doc(widget.uid)
          .set({
            'weight': weight,
            'height': height,
            'bodyType': _selectedBodyType,
            'bmi': bmi.toStringAsFixed(1),
            'profileComplete': true,
            'updatedAt': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));

      // Navigate to profile page
      Navigator.pushReplacement(context, 
        MaterialPageRoute(builder: (_) => ProfilePage(uid: widget.uid)));

    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error: ${e.toString()}')));
    } finally {
      setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Body Metrics')),
      body: SingleChildScrollView(
        padding: EdgeInsets.all(20),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              // Weight Field
              TextFormField(
                controller: _weightController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(
                  labelText: 'Weight (kg)',
                  suffixText: 'kg'
                ),
                validator: (value) {
                  if (value == null || value.isEmpty) {
                    return 'Please enter your weight';
                  }
                  final weight = double.tryParse(value);
                  if (weight == null || weight <= 0 || weight > 300) {
                    return 'Please enter a valid weight (0-300kg)';
                  }
                  return null;
                },
              ),
              SizedBox(height: 20),

              // Height Field
              TextFormField(
                controller: _heightController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(
                  labelText: 'Height (cm)',
                  suffixText: 'cm'
                ),
                validator: (value) {
                  if (value == null || value.isEmpty) {
                    return 'Please enter your height';
                  }
                  final height = double.tryParse(value);
                  if (height == null || height <= 0 || height > 250) {
                    return 'Please enter a valid height (0-250cm)';
                  }
                  return null;
                },
              ),
              SizedBox(height: 20),

              // Body Type Dropdown
              DropdownButtonFormField<String>(
                value: _selectedBodyType,
                decoration: InputDecoration(labelText: 'Body Type'),
                items: _bodyTypes.map((type) {
                  return DropdownMenuItem(
                    value: type,
                    child: Text(type),
                  );
                }).toList(),
                onChanged: (value) => setState(() => _selectedBodyType = value),
                validator: (value) {
                  if (value == null) return 'Please select your body type';
                  return null;
                },
              ),
              SizedBox(height: 30),

              // Submit Button
              ElevatedButton(
                onPressed: _isLoading ? null : _submitForm,
                child: _isLoading
                    ? CircularProgressIndicator()
                    : Text('Complete Profile'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
